//! This file was not tested because there is no DOMRect inside js-dom, should cover it in the future
import React, { forwardRef } from 'react';
import * as TooltipRadix from '@radix-ui/react-tooltip';
import { theme } from '@hexa-ui/theme';
import { TooltipProps } from './Tooltip.types';

import {
  StyledTooltipRoot,
  StyledTooltipTrigger,
  StyledTooltipContent,
  StyledTooltipArrow,
} from './Tooltip.styles';

const spacingValue = theme.space[2]?.value;
const spacingAsNumber = Number(spacingValue.split('rem')[0]) * 16;

const Tooltip = forwardRef<HTMLDivElement, TooltipProps>(
  ({ text, placement = 'bottom', children }, forwardedRef): JSX.Element => (
    <TooltipRadix.Provider delayDuration={300}>
      <StyledTooltipRoot>
        <StyledTooltipTrigger data-testid="tooltip" asChild>
          <div>{children}</div>
        </StyledTooltipTrigger>
        <StyledTooltipContent
          sideOffset={spacingAsNumber}
          side={placement}
          align="center"
          ref={forwardedRef}
        >
          {text}
          <StyledTooltipArrow />
        </StyledTooltipContent>
      </StyledTooltipRoot>
    </TooltipRadix.Provider>
  )
);

export default Tooltip;
